// Step 1: Access nested JSON inside Data.Result
const data = items[0].json?.Data?.Result || [];

// Step 2: Handle empty data
if (!Array.isArray(data) || data.length === 0) {
  return [{ json: { message: "No data received from API (Data.Result empty)" } }];
}

// 🌴 Step 2.1: Define Holidays (YYYY-MM-DD)
const holidays = [
  "2025-10-02", // Gandhi Jayanti

];

// Step 3: Convert YYYY-MM-DD → D/M/YYYY
function formatDate(isoDate) {
  if (!isoDate) return "";
  const [year, month, day] = isoDate.split("-");
  return `${parseInt(day)}/${parseInt(month)}/${year}`;
}

// Step 4: Extract all unique dates
const allDates = [...new Set(data.map(d => d.Date.split("T")[0]))].sort();

// Step 5: Group by employee
const grouped = {};
data.forEach(d => {
  const empName = d.EmployeeName?.trim() || "Unknown";
  const desig = d.Designation || "N/A";
  const dateKey = d.Date.split("T")[0];
  const key = `${empName}|${desig}`;

  if (!grouped[key]) {
    grouped[key] = {
      EmployeeName: empName,
      Designation: desig,
    };
    // Initialize each date as blank first
    allDates.forEach(date => {
      grouped[key][formatDate(date)] = "";
    });
  }

  // Convert hours to integer (round if decimal)
  const hours = Number.isFinite(d.Hrs) ? Math.round(d.Hrs) : 0;
  grouped[key][formatDate(dateKey)] = hours;
});

// Step 6: Mark holidays as 0 for everyone
Object.values(grouped).forEach(emp => {
  allDates.forEach(date => {
    if (holidays.includes(date)) {
      const formattedDate = formatDate(date);
      emp[formattedDate] = 0; // mark as 0 for holidays
    }
  });
});

// Step 7: Return grouped rows
return Object.values(grouped).map(row => ({ json: row }));

